import 'dart:convert';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

/// Review reproduction 2: WindowedSessionStorage.getPathToRoot truncation
/// when records sit in _appendedBelow (deep-paged external appends).
void main() {
  const sessionPath = '/sessions/walk.jsonl';

  String headerLine([
    String timestamp = '2026-09-07T00:00:00.000Z',
    String id = 'walk',
  ]) => jsonEncode({
    'type': 'session',
    'version': 3,
    'id': id,
    'timestamp': timestamp,
    'cwd': '/work',
  });

  String messageLine(
    String id, {
    String? parentId,
  }) => jsonEncode({
    'type': 'message',
    'id': id,
    'parentId': ?parentId,
    'timestamp': '2026-09-07T00:00:01.000Z',
    'message': {'role': 'user', 'content': 'hi'},
  });

  test('REPRO 2: a below-window chain longer than the resident set '
      'truncates getPathToRoot', () async {
    final fs = MemoryFileSystem(cwd: '/');
    final lines = <String>[headerLine()];
    for (var i = 1; i <= 650; i++) {
      lines.add(messageLine('m$i', parentId: i == 1 ? null : 'm${i - 1}'));
    }
    await fs.writeFile(sessionPath, lines.join('\n'));

    final storage = await WindowedSessionStorage.open(fs, sessionPath);
    expect(storage.hasOlder, isTrue);

    // Deep-page: re-center the window at an OLD record, so the file tail
    // sits below the window bottom (the jumpToRecord flow).
    final jumped = await storage.jumpToRecord('m1');
    expect(jumped, isNotEmpty);

    // A second process appends 250 records chained from m650 (the file
    // tail — below the window). The gh-2178 incident's shared-file class.
    final appended = <String>[];
    for (var i = 1; i <= 250; i++) {
      appended.add(
        messageLine('x$i', parentId: i == 1 ? 'm650' : 'x${i - 1}'),
      );
    }
    await fs.appendFile(sessionPath, '\n${appended.join('\n')}');

    // Ingest the external appends (the app transcript-poll flow).
    final ingested = await storage.ingestAppended();
    expect(ingested.reanchored, isFalse);

    // Walk the newest appended record up to the root.
    final path = await storage.getPathToRoot('x250');
    expect(
      path.map((r) => r.id),
      hasLength(250),
      reason: 'the full below-window chain x1..x250 must walk — '
          'origin/main returned all of it',
    );
  });
}

